INSERT INTO invocation_capacite_commune (id, invocation_id, rang, nom, nom_cle, texte, origine, source_ref, remarque) VALUES ('bestiaire/animation-des-morts#commune:elementaire', 'bestiaire/animation-des-morts', 2, 'Élémentaire', 'elementaire', 'Chaque créature possède la/les résistances magiques ainsi que la/les vulnérabilités magiques de son élément (sauf capacité lui donnant autre chose). [Exemple. Celui du feu est résistance au Feu, Terre et Glace mais est vulnérable au Vent et à l''Eau]. Chaque attaque physique de leur part est une attaque élémentaire.', 'bestiaire', 'Invocation › Animation des morts › AP3:BE38', NULL);
INSERT INTO invocation_capacite_commune (id, invocation_id, rang, nom, nom_cle, texte, origine, source_ref, remarque) VALUES ('bestiaire/animation-des-morts#commune:non-mort', 'bestiaire/animation-des-morts', 1, 'Non-Mort', 'non-mort', 'Une créature non-mort est immunisée à la peur, à la couardise, à la fatigue, au poison, à la maladie. Les soins de lumière lui infligent des dégâts mais il a la possibilité de faire un jet de défense pour ne pas prendre les dégâts.', 'bestiaire', 'Invocation › Animation des morts › AP3:BE38', NULL);
INSERT INTO invocation_capacite_commune (id, invocation_id, rang, nom, nom_cle, texte, origine, source_ref, remarque) VALUES ('bestiaire/appel-aux-golems#commune:elementaire', 'bestiaire/appel-aux-golems', 2, 'Élémentaire', 'elementaire', 'Chaque créature possède la/les résistances magiques ainsi que la/les vulnérabilités magiques de son élément. [Exemple. Celui du feu est résistant au Feu, Terre et Glace mais est vulnérable au Vent et à l''Eau]. Chaque attaque physique de leur part est une attaque élémentaire. (Le Golem d''Argile ne possède pas cette capacité)', 'bestiaire', 'Invocation › Appel aux golems › AJ3:AY38', NULL);
INSERT INTO invocation_capacite_commune (id, invocation_id, rang, nom, nom_cle, texte, origine, source_ref, remarque) VALUES ('bestiaire/appel-aux-golems#commune:inerte', 'bestiaire/appel-aux-golems', 1, 'Inerte', 'inerte', 'Boost la volonté à 10, ce qui permet d''être immunisé au jet de volonté.', 'bestiaire', 'Invocation › Appel aux golems › AJ3:AY38', NULL);
